function zynkoSystemLog(string $level,string $module,string $message,array $context=[]): void {
  if(!in_array($level,['info','warning','error'],true))$level='info';
  try{$pdo=appDb();$tid=(int)($_SESSION['user']['tenant_id']??mainTenantId());$uid=(int)($_SESSION['user']['id']??0);$safe=$context;foreach(['password','smtp_password','client_secret','imap_password','token','secret','authorization'] as $secret){if(array_key_exists($secret,$safe))$safe[$secret]='[protegido]';}$pdo->prepare('INSERT INTO system_event_logs(tenant_id,user_id,level,module,message,context_json) VALUES(?,?,?,?,?,?)')->execute([$tid,$uid?:null,$level,mb_substr($module,0,120),mb_substr($message,0,500),$safe?json_encode($safe,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null]);}catch(Throwable $ignore){}
}
function jsonOut(bool $ok,string $message,array $data=[]): never {
  if($_SERVER['REQUEST_METHOD']==='POST' && isset($_SESSION['user'])){try{if($ok)zynkoNotifyAdministrativeAction((string)($_POST['action']??''),$message,$data);zynkoSystemLog($ok?'info':'warning','admin_action',$message,['action'=>(string)($_POST['action']??''),'data'=>$data]);}catch(Throwable $e){}}
  header('Content-Type: application/json; charset=utf-8'); echo json_encode(['ok'=>$ok,'message'=>$message,'data'=>$data],JSON_UNESCAPED_UNICODE); exit;
}
function uuid4(): string { $d=random_bytes(16);$d[6]=chr((ord($d[6])&0x0f)|0x40);$d[8]=chr((ord($d[8])&0x3f)|0x80);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($d),4)); }
function encryptSecret(string $plain): ?string { if($plain==='')return null; global $root;$e=envConfig($root.'/.env');$hex=$e['APP_KEY']??'';if(!preg_match('/^[a-f0-9]{64}$/i',$hex))throw new RuntimeException('APP_KEY inválida.');$iv=random_bytes(12);$tag='';$c=openssl_encrypt($plain,'aes-256-gcm',hex2bin($hex),OPENSSL_RAW_DATA,$iv,$tag);if($c===false)throw new RuntimeException('No se pudo cifrar.');return 'enc:v1:'.base64_encode($iv.$tag.$c); }
function zynkoLegalPlainToHtml(string $text): string {
  $text=trim($text);if($text==='')return '';
  $out='';foreach(preg_split('/\R{2,}/u',$text)?:[] as $block){$block=trim($block);if($block==='')continue;$lines=preg_split('/\R/u',$block)?:[];$first=trim((string)array_shift($lines));$rest=trim(implode("\n",$lines));if(preg_match('/^([0-9]+[.)]|[A-ZÁÉÍÓÚÑ][.)])\s+(.+)$/u',$first)){$out.='<h3>'.htmlspecialchars($first,ENT_QUOTES,'UTF-8').'</h3>';if($rest!=='')$out.='<p>'.nl2br(htmlspecialchars($rest,ENT_QUOTES,'UTF-8')).'</p>';}else{$whole=trim($first.($rest!==''?"\n".$rest:''));if($whole!=='')$out.='<p>'.nl2br(htmlspecialchars($whole,ENT_QUOTES,'UTF-8')).'</p>';}}
  return $out;
}
function zynkoSanitizeLegalHtml(string $html): string {
  $html=trim($html);if($html==='')return '';
  if($html===strip_tags($html))return zynkoLegalPlainToHtml($html);
  if(!class_exists('DOMDocument')){
    $clean=strip_tags($html,'<p><br><strong><b><em><i><u><h2><h3><h4><ul><ol><li><blockquote><a><hr>');
    return preg_replace_callback("/<\\s*(\\/?)\\s*([a-z0-9]+)([^>]*)>/i",function($m){
      $closing=$m[1]==='/';$tag=strtolower($m[2]);$void=in_array($tag,['br','hr'],true);
      if($closing)return $void?'':'</'.$tag.'>';
      $attrs='';
      if($tag==='a'&&preg_match("/href\\s*=\\s*([\\\"'])(.*?)\\1/i",$m[3],$hm)&&preg_match('#^(https?://|mailto:|tel:|/)#i',trim($hm[2])))$attrs.=' href="'.htmlspecialchars(trim($hm[2]),ENT_QUOTES,'UTF-8').'" target="_blank" rel="noopener noreferrer"';
      if(preg_match("/style\\s*=\\s*([\\\"'])(text-align\\s*:\\s*(left|center|right|justify)\\s*;?)\\1/i",$m[3],$sm))$attrs.=' style="'.htmlspecialchars($sm[2],ENT_QUOTES,'UTF-8').'"';
      return '<'.$tag.$attrs.'>';
    },$clean)??'';
  }
  $allowed=['p','br','strong','b','em','i','u','h2','h3','h4','ul','ol','li','blockquote','a','hr'];
  $dom=new DOMDocument('1.0','UTF-8');$prev=libxml_use_internal_errors(true);$dom->loadHTML('<?xml encoding="utf-8" ?><div id="zynko-legal-root">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);libxml_clear_errors();libxml_use_internal_errors($prev);
  $rootNode=$dom->getElementById('zynko-legal-root');if(!$rootNode)return '';
  $walk=function($node) use (&$walk,$allowed){foreach(iterator_to_array($node->childNodes) as $child){if($child->nodeType===XML_ELEMENT_NODE){$tag=strtolower($child->nodeName);if(!in_array($tag,$allowed,true)){$frag=$child->ownerDocument->createDocumentFragment();while($child->firstChild)$frag->appendChild($child->firstChild);$child->parentNode->replaceChild($frag,$child);continue;}if($child->hasAttributes()){foreach(iterator_to_array($child->attributes) as $attr){$name=strtolower($attr->name);$value=trim($attr->value);$keep=false;if($tag==='a'&&$name==='href'&&preg_match('#^(https?://|mailto:|tel:|/)#i',$value))$keep=true;if($name==='style'&&preg_match('/^text-align\s*:\s*(left|center|right|justify)\s*;?$/i',$value))$keep=true;if(!$keep)$child->removeAttribute($attr->name);}if($tag==='a'&&$child->hasAttribute('href')){$child->setAttribute('target','_blank');$child->setAttribute('rel','noopener noreferrer');}}$walk($child);}}};$walk($rootNode);
  $out='';foreach($rootNode->childNodes as $child)$out.=$dom->saveHTML($child);return trim($out);
}
function zynkoLegalContentToHtml(string $content): string { return zynkoSanitizeLegalHtml($content); }

function mainTenantId(): int {
    try{
        $pdo=appDb();
        $sql="SELECT id FROM tenants
              WHERE LOWER(REPLACE(TRIM(name),' ','')) IN ('esmultiservicios','esmultsiervicios')
                 OR LOWER(slug) LIKE 'es-multiservicios%'
                 OR LOWER(slug) LIKE 'es-multsiervicios%'
              ORDER BY id ASC LIMIT 1";
        $id=(int)($pdo->query($sql)->fetchColumn()?:0);
        if($id>0)return $id;
        return (int)$pdo->query('SELECT MIN(id) FROM tenants')->fetchColumn();
    }catch(Throwable $e){return 0;}
}
function zynkoNormalizeWebchatDomain(string $domain): string {
    $domain=strtolower(trim($domain));
    $domain=preg_replace('#^https?://#','',$domain);
    $domain=preg_replace('#/.*$#','',$domain);
    $domain=preg_replace('/:\\d+$/','',$domain);
    return preg_replace('/^www\\./','',$domain);
}
function zynkoCanonicalWebchatHost(): string {
    global $root;
    $host='';
    try{
        $q=appDb()->prepare("SELECT setting_value FROM system_settings WHERE setting_key='seo_site_url' LIMIT 1");
        $q->execute();
        $configured=trim((string)($q->fetchColumn()?:''));
        if($configured!=='')$host=(string)(parse_url($configured,PHP_URL_HOST)?:'');
    }catch(Throwable $e){}
    if($host===''){
        $env=envConfig($root.'/.env');
        $configured=trim((string)($env['APP_URL']??''));
        if($configured!=='')$host=(string)(parse_url($configured,PHP_URL_HOST)?:'');
    }
    if($host==='')$host=(string)($_SERVER['HTTP_HOST']??'');
    return zynkoNormalizeWebchatDomain($host);
}
function zynkoEnsureOfficialWebchatInstallation(PDO $pdo,int $tenantId,int $widgetId): array {
    if($tenantId!==mainTenantId()||$widgetId<=0)return ['id'=>0,'domain'=>'','installation_key'=>''];
    $canonicalHost=zynkoCanonicalWebchatHost();
    if($canonicalHost==='')return ['id'=>0,'domain'=>'','installation_key'=>''];

    $q=$pdo->prepare('SELECT * FROM webchat_installations WHERE tenant_id=? AND widget_id=? ORDER BY id ASC');
    $q->execute([$tenantId,$widgetId]);
    $rows=$q->fetchAll();

    $keeper=null;
    foreach($rows as $row){
        if(zynkoNormalizeWebchatDomain((string)($row['domain']??''))===$canonicalHost){$keeper=$row;break;}
    }
    if(!$keeper){
        foreach($rows as $row){
            if(empty($row['created_by'])){$keeper=$row;break;}
        }
    }

    if($keeper){
        $keeperId=(int)$keeper['id'];
        $key=trim((string)($keeper['installation_key']??''));
        if($key==='')$key=bin2hex(random_bytes(20));
        $label=trim((string)($keeper['label']??''));
        if($label==='')$label='Sitio principal ZYNKO';
        $pdo->prepare('UPDATE webchat_installations SET installation_key=?,domain=?,label=?,enabled=1,created_by=NULL WHERE id=? AND tenant_id=?')->execute([$key,$canonicalHost,$label,$keeperId,$tenantId]);
    }else{
        $key=bin2hex(random_bytes(20));
        $pdo->prepare("INSERT INTO webchat_installations(tenant_id,widget_id,installation_key,domain,label,enabled,created_by) VALUES(?,?,?,?,'Sitio principal ZYNKO',1,NULL)")->execute([$tenantId,$widgetId,$key,$canonicalHost]);
        $keeperId=(int)$pdo->lastInsertId();
        $label='Sitio principal ZYNKO';
    }

    // Limpia instalaciones automáticas heredadas creadas por hosts/alias anteriores.
    // Los sitios autorizados manualmente (IZZY, ES MULTISERVICIOS, clientes, etc.) conservan created_by y nunca se tocan aquí.
    $cleanup=$pdo->prepare('DELETE FROM webchat_installations WHERE tenant_id=? AND widget_id=? AND id<>? AND created_by IS NULL');
    $cleanup->execute([$tenantId,$widgetId,$keeperId]);

    // Evita también duplicados manuales accidentales del mismo dominio oficial.
    $dupes=$pdo->prepare('SELECT id,domain FROM webchat_installations WHERE tenant_id=? AND widget_id=? AND id<>?');
    $dupes->execute([$tenantId,$widgetId,$keeperId]);
    foreach($dupes->fetchAll() as $row){
        if(zynkoNormalizeWebchatDomain((string)$row['domain'])===$canonicalHost){
            $pdo->prepare('DELETE FROM webchat_installations WHERE id=? AND tenant_id=?')->execute([(int)$row['id'],$tenantId]);
        }
    }

    return ['id'=>$keeperId,'domain'=>$canonicalHost,'installation_key'=>$key,'label'=>$label];
}

function zynkoRunServiceCommand(string $command): array {
    $disabled=array_filter(array_map('trim',explode(',',strtolower((string)ini_get('disable_functions')))));
    $isAllowed=static fn(string $fn): bool => function_exists($fn) && !in_array(strtolower($fn),$disabled,true);
    $output='';$code=1;$backend='';
    if($isAllowed('exec')){
        $lines=[];@exec($command.' 2>&1',$lines,$code);$output=implode("\n",$lines);$backend='exec';
    } elseif($isAllowed('proc_open')){
        $desc=[1=>['pipe','w'],2=>['pipe','w']];$pipes=[];$proc=@proc_open($command,$desc,$pipes);
        if(is_resource($proc)){ $output=(string)stream_get_contents($pipes[1]).(string)stream_get_contents($pipes[2]);foreach($pipes as $pipe)if(is_resource($pipe))fclose($pipe);$code=proc_close($proc);$backend='proc_open';}
    } elseif($isAllowed('shell_exec')){
        $token='__ZYNKO_EXIT__';$raw=(string)@shell_exec($command.' 2>&1; printf "\n'.$token.'%s" "$?"');$backend='shell_exec';
        if(preg_match('/\n'.$token.'(\d+)\s*$/',$raw,$m)){$code=(int)$m[1];$output=preg_replace('/\n'.$token.'\d+\s*$/','',$raw)??$raw;}else{$output=$raw;$code=$raw!==''?0:1;}
    } elseif($isAllowed('system')){
        ob_start();@system($command.' 2>&1',$code);$output=(string)ob_get_clean();$backend='system';
    } elseif($isAllowed('passthru')){
        ob_start();@passthru($command.' 2>&1',$code);$output=(string)ob_get_clean();$backend='passthru';
    } elseif($isAllowed('popen')){
        $h=@popen($command.' 2>&1','r');if(is_resource($h)){while(!feof($h))$output.=fgets($h);$status=pclose($h);$code=is_int($status)?$status:1;$backend='popen';}
    }
    return ['available'=>$backend!=='','backend'=>$backend,'code'=>(int)$code,'output'=>trim($output)];
}
