  function zynkoPdfEsc(string $s): string { $x=@iconv('UTF-8','Windows-1252//TRANSLIT',preg_replace('/\s+/u',' ',trim($s)));if($x===false)$x=$s;return str_replace(["\\","(",")"],["\\\\","\\(","\\)"],$x); }
  function zynkoPdfWrap(string $text,int $max): array { $text=trim(preg_replace('/\s+/u',' ',$text));if($text==='')return [''];$words=preg_split('/\s+/u',$text);$out=[];$line='';foreach($words as $w){$test=$line===''?$w:$line.' '.$w;if((function_exists('mb_strlen')?mb_strlen($test):strlen($test))<=$max)$line=$test;else{if($line!=='')$out[]=$line;$line=$w;}}if($line!=='')$out[]=$line;return $out?:['']; }
  function zynkoExportPdf(string $filename,string $title,string $subtitle,array $cards,string $view='detail'): void {
    $view=$view==='mini'?'mini':'detail';$pageW=612;$pageH=842;$margin=34;$contentTop=706;$footerY=28;$gap=12;$cardW=$view==='mini'?260:544;$cardH=$view==='mini'?132:92;$cols=$view==='mini'?2:1;$xPositions=$view==='mini'?[34,318]:[34];$rowsPerPage=$view==='mini'?4:6;$perPage=$cols*$rowsPerPage;$pages=array_chunk($cards?:[['title'=>'Sin registros','lines'=>['No hay información disponible para este reporte.']]],$perPage);
    $objects=[];$pageObjs=[];$contentObjs=[];$obj=5;foreach($pages as $_){$pageObjs[]=$obj++;$contentObjs[]=$obj++;}$objects[1]='<< /Type /Catalog /Pages 2 0 R >>';$objects[2]='<< /Type /Pages /Kids [ '.implode(' ',array_map(fn($n)=>$n.' 0 R',$pageObjs)).' ] /Count '.count($pageObjs).' >>';$objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';$objects[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>';
    foreach($pages as $pi=>$pageCards){$stream="q\n0.059 0.463 0.431 rg\n0 754 612 88 re f\nQ\nBT\n/F4 20 Tf\n1 1 1 rg\n36 808 Td\n(".zynkoPdfEsc($title).") Tj\n/F3 9 Tf\n0 -24 Td\n(".zynkoPdfEsc($subtitle).") Tj\nET\nq\n0.933 0.973 0.961 rg\n34 714 544 28 re f\nQ\nBT\n/F4 8 Tf\n0.16 0.35 0.33 rg\n44 724 Td\n(".zynkoPdfEsc('Vista '.($view==='mini'?'miniatura':'detalle').' · Total '.count($cards).' · Generado '.date('d/m/Y H:i').' · Página '.($pi+1).' de '.count($pages)).") Tj\nET\n";
      foreach($pageCards as $idx=>$card){$col=$idx%$cols;$row=intdiv($idx,$cols);$x=$xPositions[$col];$y=$contentTop-($row+1)*$cardH-$row*$gap+12;$stream.="q\n0.985 0.992 0.990 rg\n$x $y $cardW $cardH re f\n0.84 0.90 0.89 RG\n$x $y $cardW $cardH re S\nQ\nBT\n/F4 ".($view==='mini'?10:11)." Tf\n0.06 0.13 0.20 rg\n".($x+14).' '.($y+$cardH-24)." Td\n(".zynkoPdfEsc((string)($card['title']??'')).") Tj\n/F3 8 Tf\n0.25 0.34 0.42 rg\n"; $dy=16;$maxChars=$view==='mini'?48:92;$maxLines=$view==='mini'?5:4;$written=0;foreach(($card['lines']??[]) as $line){foreach(zynkoPdfWrap((string)$line,$maxChars) as $wl){if($written>=$maxLines)break 2;$stream.="0 -$dy Td\n(".zynkoPdfEsc($wl).") Tj\n";$written++;}}$stream.="ET\n";}
      $stream.="q\n0.84 0.90 0.91 RG\n34 42 m 578 42 l S\nQ\nBT\n/F3 7 Tf\n0.42 0.50 0.57 rg\n36 $footerY Td\n(".zynkoPdfEsc('ZYNKO · Reporte ejecutivo · uso administrativo').") Tj\nET\n";$objects[$contentObjs[$pi]]='<< /Length '.strlen($stream).' >>'."\nstream\n".$stream."endstream";$objects[$pageObjs[$pi]]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F3 3 0 R /F4 4 0 R >> >> /Contents '.$contentObjs[$pi].' 0 R >>';}
    ksort($objects);$pdf="%PDF-1.4\n";$offset=[0=>0];foreach($objects as $n=>$body){$offset[$n]=strlen($pdf);$pdf.=$n." 0 obj\n".$body."\nendobj\n";}$xref=strlen($pdf);$max=max(array_keys($objects));$pdf.="xref\n0 ".($max+1)."\n0000000000 65535 f \n";for($i=1;$i<=$max;$i++)$pdf.=sprintf('%010d 00000 n ', $offset[$i]??0)."\n";$pdf.="trailer\n<< /Size ".($max+1)." /Root 1 0 R >>\nstartxref\n".$xref."\n%%EOF";header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Content-Length: '.strlen($pdf));header('Cache-Control: no-store');echo $pdf;exit;
  }
